mapper.select:
select , c.name as contractor_name
from cbs.t_project p left join cbs.t_contractor c on c.contractor_id = p.contractor_id
where p.project_id = #{id}

mapper.update:
update cbs.t_project
contractor_id = #{p.contractor_id}, proj_name = #{p.proj_name}, proj_content = #{p.proj_content}, begin_date = #{p.begin_date}, end_date = #{p.end_date}, proj_status = #{p.proj_status}, dept_code = #{p.dept_code},
where project_id = #{p.project_id}
